// CONFIGURATION : comptes X à suivre (handle sans @). Ajoute-les ici.
const COMPTES_X = [
  // 'compte1',
  // 'compte2',
];

// Paquets de comptes par requête (X limite la longueur d'une recherche)
const PAR_REQUETE = 10;

const staticData = $getWorkflowStaticData('global');
const now = Date.now();

// Passage du matin (LinkedIn + X) ou de l'après-midi (X seulement)
const heure = Number(new Date().toLocaleString('en-US', { timeZone: 'America/Toronto', hour: 'numeric', hour12: false }));
const matin = heure < 12;

// Fenêtre X : depuis le dernier passage réussi, 24 h max, + 15 min de marge (les doublons sont filtrés ensuite)
const dernier = staticData.lastXRun || 0;
const fenetre = Math.min(now - dernier, 24 * 36e5) + 15 * 6e4;
const sinceTime = Math.floor((now - fenetre) / 1000);

const comptes = [...new Set(COMPTES_X.map(c => String(c).trim().replace(/^@/, '').replace(/^https?:\/\/(www\.)?(x|twitter)\.com\//i, '').split(/[/?]/)[0]).filter(Boolean))];
const xQueries = [];
for (let i = 0; i < comptes.length; i += PAR_REQUETE) {
  const paquet = comptes.slice(i, i + PAR_REQUETE).map(c => `from:${c}`).join(' OR ');
  xQueries.push(`(${paquet}) since_time:${sinceTime} -filter:replies -filter:retweets`);
}

return [{ json: { matin, xQueries, nbComptes: comptes.length, depuis: new Date(sinceTime * 1000).toISOString(), runAt: now } }];

// LinkedIn : dédoublonne et score les posts (même logique que l'ancien workflow).
// La mémoire des posts déjà vus ne persiste qu'en exécution automatique (workflow actif).
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
for (const [k, t] of Object.entries(staticData.seen)) {
  if (now - t > 30 * 864e5) delete staticData.seen[k];
}

const metier = /\b(revops|revenue operations|sales ops|sales operations|marketing ops|marketing operations|gtm|go-to-market|hubspot|salesforce|crm)\b/gi;
const decideur = /\b(founder|co-founder|ceo|coo|cro|vp|head of|director|chief|owner)\b/i;
const recruteur = /\b(recruit\w*|talent|sourc\w*|staffing|headhunt\w*)\b/i;
const contact = /(dm me|send me a (dm|message)|reach out|comment below|drop a comment|email me)/i;

const items = $input.all().map(i => i.json || {});
const erreur = items.find(p => p.error) ? 'Erreur Apify LinkedIn : ' + String(items.find(p => p.error).error.message || items.find(p => p.error).error).slice(0, 200) : '';

const posts = [];
for (const p of items) {
  const key = p.id || p.linkedinUrl;
  if (!key || staticData.seen[key]) continue;
  staticData.seen[key] = now;

  const text = p.content || '';
  const headline = (p.author && p.author.info) || '';
  const hits = [...new Set((text.match(metier) || []).map(h => h.toLowerCase()))];
  const tags = [];
  let score = Math.min(hits.length, 3) * 20;
  if (/\b(toronto|gta|ontario)\b/i.test(text)) score += 15;
  if (/\bremote\b/i.test(text) && /\bcanada\b/i.test(text)) score += 10;
  if (decideur.test(headline)) { score += 25; tags.push('Décideur'); }
  if (recruteur.test(headline)) { score -= 10; tags.push('Recruteur'); }
  if (contact.test(text)) { score += 10; tags.push('Contact direct'); }

  posts.push({
    score, tags, hits,
    author: (p.author && p.author.name) || 'Inconnu',
    headline,
    authorUrl: (p.author && p.author.linkedinUrl) || '',
    url: p.linkedinUrl || (p.socialContent && p.socialContent.shareUrl) || '',
    when: (p.postedAt && p.postedAt.postedAgoText) || '',
    excerpt: text.replace(/\s+/g, ' ').slice(0, 300),
  });
}
posts.sort((a, b) => b.score - a.score);

return [{ json: { posts, erreur } }];

// X : filtre, dédoublonne et score les tweets des comptes suivis.
const staticData = $getWorkflowStaticData('global');
staticData.seenX = staticData.seenX || {};
staticData.avgX = staticData.avgX || {};
const now = Date.now();
for (const [k, t] of Object.entries(staticData.seenX)) {
  if (now - t > 30 * 864e5) delete staticData.seenX[k];
}

const metier = /\b(revops|revenue operations|sales ops|sales operations|marketing ops|gtm|go-to-market|hubspot|salesforce|clay|crm|outbound|pipeline|icp|abm|enrichment|signals?|cold email|sequenc\w*|forecast\w*|attribution)\b/gi;
const recrutement = /(\bhiring\b|we're hiring|we are hiring|join (our|the) team|open role|looking for (a|an) |job opening|apply here)/i;
const ressource = /(🧵|\bthread\b|\b1\/\d*\b|\btemplate|\bplaybook|\bframework|\bguide\b|\bchecklist|\bswipe file)/i;

const items = $input.all().map(i => i.json || {});
const errItem = items.find(t => t.error);
const erreur = errItem ? 'Erreur Apify X : ' + String((errItem.error && errItem.error.message) || errItem.error).slice(0, 200) : '';

const num = v => Number(v) || 0;
const tweets = [];
for (const t of items) {
  const id = t.id || t.id_str || t.tweetId;
  const text = t.text || t.fullText || t.full_text || '';
  if (!id || !text) continue; // éléments vides ou messages "aucun résultat"
  const a = t.author || t.user || {};
  const user = a.userName || a.username || a.screen_name || '';
  // Retweets et réponses à d'autres comptes exclus ; les threads (réponses à soi-même) restent
  if (t.isRetweet || t.retweeted_tweet || t.retweetedTweet || /^RT @/.test(text)) continue;
  const replyTo = t.inReplyToUsername || t.in_reply_to_screen_name || '';
  if ((t.isReply || replyTo) && replyTo.toLowerCase() !== user.toLowerCase()) continue;

  const key = String(id);
  if (staticData.seenX[key]) continue;
  staticData.seenX[key] = now;

  const likes = num(t.likeCount ?? t.favorite_count), rts = num(t.retweetCount ?? t.retweet_count), reps = num(t.replyCount ?? t.reply_count);
  const eng = likes + 2 * rts + reps;
  const created = new Date(t.createdAt || t.created_at || now).getTime() || now;
  const ageH = (now - created) / 36e5;

  const hits = [...new Set((text.match(metier) || []).map(h => h.toLowerCase()))];
  const tags = [];
  let score = Math.min(hits.length, 3) * 20;

  // Engagement comparé à la moyenne du compte (moyenne glissante mémorisée)
  const ukey = user.toLowerCase();
  const moy = staticData.avgX[ukey];
  const ratio = moy ? eng / Math.max(moy, 1) : 1;
  score += Math.min(30, Math.round(ratio * 15));
  if (ratio >= 2) tags.push('Au-dessus de sa moyenne');
  staticData.avgX[ukey] = moy ? moy * 0.8 + eng * 0.2 : eng;

  if (ageH < 6) { score += 10; tags.push('Récent'); }
  const aLien = /https?:\/\//.test(text) || (t.entities && t.entities.urls && t.entities.urls.length);
  if (aLien || ressource.test(text)) { score += 10; tags.push('Ressource'); }
  if (recrutement.test(text)) { score += 25; tags.push('Recrutement'); }

  const h = Math.round(ageH);
  tweets.push({
    score, tags, hits,
    author: a.name || user || 'Inconnu',
    headline: user ? '@' + user + (a.followers ? ' · ' + num(a.followers).toLocaleString('fr-CA') + ' abonnés' : '') : '',
    authorUrl: user ? 'https://x.com/' + user : '',
    url: t.url || t.twitterUrl || (user ? `https://x.com/${user}/status/${key}` : ''),
    when: (h < 1 ? "il y a moins d'1 h" : `il y a ${h} h`) + ` · ${likes} j'aime · ${rts} reposts · ${reps} réponses`,
    excerpt: text.replace(/\s+/g, ' ').slice(0, 300),
  });
}
tweets.sort((a, b) => b.score - a.score);

// Mémorise le passage réussi pour la fenêtre du prochain
if (!erreur) staticData.lastXRun = $('Préparer le passage').first().json.runAt;

return [{ json: { posts: tweets, erreur } }];

// Assemble un seul e-mail : section LinkedIn (matin) + section X.
const prep = $('Préparer le passage').first().json;
const lire = nom => { try { return $(nom).first().json; } catch (e) { return null; } };
const li = prep.matin ? lire('LinkedIn : dédoublonner et scorer') : null;
const x = prep.nbComptes ? lire('X : filtrer et scorer') : null;

const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const carte = (p, lien) => `
  <div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:10px 0;">
    <div style="font-size:13px;color:#666;">Score ${p.score}${p.tags.length ? ' · ' + esc(p.tags.join(' · ')) : ''}${p.when ? ' · ' + esc(p.when) : ''}</div>
    <div style="font-weight:bold;margin:4px 0;"><a href="${esc(p.authorUrl)}">${esc(p.author)}</a></div>
    <div style="font-size:13px;color:#444;">${esc(p.headline)}</div>
    <p style="font-size:14px;">${esc(p.excerpt)}${p.excerpt.length >= 300 ? '…' : ''}</p>
    <div style="font-size:12px;color:#888;">Mots-clés : ${esc(p.hits.join(', ') || 'aucun')}</div>
    <a href="${esc(p.url)}">${lien}</a>
  </div>`;
const section = (titre, data, vide, lien) => {
  if (!data) return '';
  const err = data.erreur ? `<p style="color:#b00;">${esc(data.erreur)}</p>` : '';
  const corps = data.posts.length ? `<p>${data.posts.length} nouveaux, triés par score.</p>` + data.posts.map(p => carte(p, lien)).join('') : `<p>${vide}</p>`;
  return `<h3>${titre}</h3>${err}${corps}`;
};

const nLi = li ? li.posts.length : 0;
const nX = x ? x.posts.length : 0;
const erreurs = [li && li.erreur, x && x.erreur].filter(Boolean).length;

const date = new Date().toLocaleDateString('fr-CA', { timeZone: 'America/Toronto', weekday: 'long', day: 'numeric', month: 'long' });
const titre = prep.matin ? `Signaux du jour, ${date}` : `Signaux X de l'après-midi, ${date}`;
let html = `<h2>${esc(titre)}</h2>`;
html += section('💼 LinkedIn : recrutements Toronto', li, 'Rien de nouveau sur LinkedIn.', 'Voir le post');
if (prep.nbComptes) html += section('🐦 X : comptes GTM suivis', x, 'Rien de nouveau sur X depuis le dernier passage.', 'Voir le tweet');
else html += '<h3>🐦 X</h3><p>Aucun compte configuré (nœud « Préparer le passage »).</p>';

const subject = prep.matin ? `Signaux du jour : ${nLi} LinkedIn, ${nX} X` : `Signaux X : ${nX} nouveaux tweets`;

// Pas d'e-mail si rien de neuf et aucune erreur à signaler
return [{ json: { envoyer: nLi + nX > 0 || erreurs > 0, subject, html } }];
